import{_ as n,o as s,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"12. Constants, Literals, and Enumerations","description":"The Little Book of C — 12. Constants, Literals, and Enumerations","frontmatter":{"title":"12. Constants, Literals, and Enumerations","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Language Basics"],"description":"The Little Book of C — 12. Constants, Literals, and Enumerations","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":12,"sidebarWeight":12,"lang":"en-US","alternateEn":"/posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations","alternateZh":"/posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations"},"headers":[],"relativePath":"posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations.md","filePath":"posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations.md"};function o(p,a,l,r,c,d){return s(),e("div",null,[...a[0]||(a[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations)</p><p>C programs often rely on values that never change, numbers, characters, or named constants used throughout your code. Instead of sprinkling magic numbers everywhere, you can give them meaningful names and keep your program readable, safe, and easy to maintain.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define PI 3.14159</span><span>           // preprocessor constant</span></span>
<span class="line"><span>const int DAYS_IN_WEEK = 7;  // read-only variable</span></span>
<span class="line"><span>enum Direction { NORTH, EAST, SOUTH, WEST }; // enumerated constants</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Pi: %.2f\\n&quot;, PI);</span></span>
<span class="line"><span>    printf(&quot;Days in a week: %d\\n&quot;, DAYS_IN_WEEK);</span></span>
<span class="line"><span>    printf(&quot;Direction EAST has value: %d\\n&quot;, EAST);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pi: 3.14</span></span>
<span class="line"><span>Days in a week: 7</span></span>
<span class="line"><span>Direction EAST has value: 1</span></span></code></pre></div><h4 id="constants-in-c" tabindex="-1">Constants in C <a class="header-anchor" href="#constants-in-c" aria-label="Permalink to &quot;Constants in C&quot;">​</a></h4><p>Preprocessor constants (<code>#define</code>) These are replaced before compilation. Think of them as text substitutions, not variables.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAX_USERS 100</span></span>
<span class="line"><span>printf(&quot;Max users: %d\\n&quot;, MAX_USERS);</span></span></code></pre></div><ul><li>No memory is used.</li><li>No type checking, the compiler just replaces the text.</li></ul><p>Constant variables (<code>const</code>) These are real variables stored in memory but cannot be modified after initialization.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const double SPEED_OF_LIGHT = 299792458.0;</span></span></code></pre></div><ul><li>Type safe.</li><li>Preferred for constants in modern C code.</li></ul><p>Literals These are fixed values written directly in your code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>42          // integer literal</span></span>
<span class="line"><span>3.14        // floating-point literal</span></span>
<span class="line"><span>&#39;A&#39;</span><span>         // character literal</span></span>
<span class="line"><span>&quot;Hello&quot;</span><span>     // string literal</span></span>
<span class="line"><span>0xFF        // hexadecimal literal (255)</span></span>
<span class="line"><span>075         // octal literal (61)</span></span></code></pre></div><h4 id="enumerations" tabindex="-1">Enumerations <a class="header-anchor" href="#enumerations" aria-label="Permalink to &quot;Enumerations&quot;">​</a></h4><p>An enum (short for enumeration) defines a set of named integer constants. They make your code self-documenting and prevent mistakes with raw numbers.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum TrafficLight {</span></span>
<span class="line"><span>    RED,     // 0</span></span>
<span class="line"><span>    YELLOW,  // 1</span></span>
<span class="line"><span>    GREEN    // 2</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    enum TrafficLight signal = GREEN;</span></span>
<span class="line"><span>    if (signal == GREEN)</span></span>
<span class="line"><span>        printf(&quot;Go!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>You can also assign custom values:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum Month {</span></span>
<span class="line"><span>    JAN = 1, FEB, MAR, APR, MAY, JUN,</span></span>
<span class="line"><span>    JUL, AUG, SEP, OCT, NOV, DEC</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>Now<code>JAN</code> starts at 1, and each value increments automatically.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Constants and enums make your code clearer and safer:</p><ul><li>You can change one definition instead of many numbers.</li><li>The compiler can enforce that constants are not modified.</li><li>Enumerations group related values into a meaningful set.</li></ul><p>Without them, large programs become fragile and full of unexplained numbers, a maintenance nightmare.</p><p>Good C programmers use constants to express intent, not just values.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Replace every numeric literal in your old programs with a<code>#define</code> or<code>const</code>. Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAX_SCORE 100</span></span>
<span class="line"><span>const float TAX_RATE = 0.08;</span></span></code></pre></div><p>Create an<code>enum</code> for days of the week, and print<code>MONDAY</code> and<code>FRIDAY</code>.</p><p>Assign custom values in your enum (e.g. start with<code>SUNDAY = 1</code>).</p><p>Experiment: try changing<code>const int x = 5; x = 10;</code>, notice the compiler stops you from modifying it.</p><p>Use<code>printf</code> to print literal values in different formats:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d %x %o\\n&quot;, 255, 255, 255); // decimal, hex, octal</span></span></code></pre></div><p>Constants are how you make your C programs speak clearly. They turn numbers into ideas, and that’s what transforms code from working to understandable.</p>`,35)])])}const m=n(i,[["render",o]]);export{h as __pageData,m as default};
